$_MODULE['<{stripejs}prestashop>settings_5405d8a903c83e89cb649f1b518ef1be'] = 'Domande frequenti';
$_MODULE['<{stripejs}prestashop>settings_69c67e69bfd9f400071c211381c957a3'] = 'Da quando verranno apportate modifiche all\'utilizzo delle chiavi API riservate (RAK)?';
$_MODULE['<{stripejs}prestashop>settings_23724d662d338cee2866792690683f21'] = 'Il 29 ottobre 2024, Stripe inizierà a richiedere a tutti i commercianti che utilizzano plugin di aggiornare la sicurezza delle proprie connessioni autenticandosi con chiavi API riservate o OAuth 2.0. Si tratta di un aggiornamento pianificato per migliorare la sicurezza complessiva delle integrazioni di terze parti di Stripe e conformarsi ai più recenti standard di Stripe. Stripe addebiterà una commissione a partire da giugno 2025 alle aziende che non rispettano questo requisito di sicurezza.';
$_MODULE['<{stripejs}prestashop>settings_17c4d5cfff83fa78cf1121dbabf1a0b6'] = 'Perché utilizzare le chiavi API riservate (RAK)?';
$_MODULE['<{stripejs}prestashop>settings_96c286372d7630f0b772f6c8dcdce47a'] = 'Per una maggiore sicurezza e controllo, è essenziale utilizzare chiavi API riservate (RAK) o OAuth 2.0 anziché chiavi segrete per l\'autenticazione con servizi di terze parti. Le chiavi API riservate migliorano la sicurezza offrendo alle aziende un controllo preciso sulle autorizzazioni concesse a terze parti, garantendo che i servizi di terze parti accedano solo ai dati e alle azioni necessari.';
$_MODULE['<{stripejs}prestashop>settings_8a0248f6675e05ce853ad76204a8db88'] = 'Perché dobbiamo installare la vostra app \"NTS Connect\" nella nostra dashboard Stripe?';
$_MODULE['<{stripejs}prestashop>settings_2afb9e214961b24feef77706d7d6e636'] = 'Tutti gli sviluppatori di plugin, nuovi ed esistenti, devono creare un\'autorizzazione OAuth 2.0 o con chiave API limitata tramite un\'app Stripe. Tutte le app Stripe vengono sottoposte a verifica per verificarne l\'accuratezza delle autorizzazioni prima di essere pubblicate sullo Stripe App Marketplace. Seguire la procedura di installazione e installare l\'app creata da terze parti garantisce l\'accesso solo alle parti necessarie dei dati Stripe.';
$_MODULE['<{stripejs}prestashop>settings_4b02c842e5a0897f8bff4865fb9876f0'] = 'La chiave API riservata verrà generata automaticamente al termine dell\'installazione della nostra app NTS Connect.';
$_MODULE['<{stripejs}prestashop>settings_138f89513a918278f8ea688e6d9d5767'] = 'Autenticazione con chiave API limitata (RAK)';
$_MODULE['<{stripejs}prestashop>settings_5ee46c61623bc06fc49c69ad602e1aed'] = 'I pagamenti con carta supportano il nuovo requisito SCA e 3DS v2?';
$_MODULE['<{stripejs}prestashop>settings_c917d1c663625f5b8095bbe7a85e728b'] = 'Sì, dalla versione 4.1.5 di questo modulo, tutti i pagamenti con carta sono compatibili con 3DS v2 e SCA ready.';
$_MODULE['<{stripejs}prestashop>settings_633b5050e5e0a33d9f517a7966d0d80b'] = 'Qual è la differenza tra Stripe Payment Element e Stripe checkout form?';
$_MODULE['<{stripejs}prestashop>settings_2c6b97f71f993c5fff7f904d0a33419b'] = 'Elemento di pagamento Stripe';
$_MODULE['<{stripejs}prestashop>settings_1b9cffba775f6399d2e06c6b77d9ac4c'] = 'Si tratta di un modulo di pagamento incorporato, generato direttamente dalle API Stripe, che offre carte, portafogli, bonifici bancari e opzioni di pagamento locali con un\'unica integrazione.';
$_MODULE['<{stripejs}prestashop>settings_b7ec52070b5d926a3d71a20bcbf6a7c7'] = 'Accetta pagamenti tramite tutti i metodi di pagamento attivati ​​nella tua Dashboard Stripe tramite un\'unica opzione di pagamento.';
$_MODULE['<{stripejs}prestashop>settings_2d5f6de400790c233e4e308c7d34cacd'] = 'I clienti verranno reindirizzati all\'esterno solo per i metodi di pagamento di reindirizzamento della banca locale per effettuare il pagamento.';
$_MODULE['<{stripejs}prestashop>settings_93caeaee939951cb0a9bce4917cf7b4a'] = 'Fare clic per maggiori dettagli';
$_MODULE['<{stripejs}prestashop>settings_368fd6f271cf961a475abd45395e40ac'] = 'Checkout ospitato da Stripe';
$_MODULE['<{stripejs}prestashop>settings_622458ef1f201e8b5f474fe797a49100'] = 'Offri tutti i metodi di pagamento attivati ​​nella tua Dashboard Stripe tramite un\'unica opzione di pagamento.';
$_MODULE['<{stripejs}prestashop>settings_137d917afd647ecc423028cbd883d676'] = 'Apple Pay e Google Pay sono offerti per impostazione predefinita.';
$_MODULE['<{stripejs}prestashop>settings_8d657438abb997eb67eda311584c67dc'] = 'I clienti verranno reindirizzati alla pagina Checkout ospitata da Stripe per effettuare il pagamento.';
$_MODULE['<{stripejs}prestashop>settings_516e1cfee9d2877cea9b25847adc9a54'] = 'Clicca per vedere la demo';
$_MODULE['<{stripejs}prestashop>settings_03e5b907c51dc5775c8e3127b393fee1'] = 'Quali metodi di pagamento in questo modulo supportano la nuova API Payment Intent?';
$_MODULE['<{stripejs}prestashop>settings_b236b874b2b64d17268bffc9868e117e'] = 'Tutte le opzioni di pagamento utilizzano la nuova API Payment Intent.';
$_MODULE['<{stripejs}prestashop>settings_9d1b45c90be64fc8e5439b42afd343d8'] = 'Stripe Radar è supportato?';
$_MODULE['<{stripejs}prestashop>settings_fb796d3d45c52439dcd229cd35bee1c5'] = 'Sì, se disponibile per il tuo account Stripe, puoi utilizzare Stripe Radar con questo modulo.';
$_MODULE['<{stripejs}prestashop>settings_c395c1a8b6c7d29dc03cb0ae088d14fe'] = 'Come posso aggiungere manualmente il mio nome di dominio nella dashboard di Stripe per utilizzare ApplePay?';
$_MODULE['<{stripejs}prestashop>settings_a14c8a138090469edaece24fce8bba88'] = 'Puoi aggiungere manualmente i tuoi domini tramite la tua dashboard. Puoi farlo facilmente seguendo i passaggi:';
$_MODULE['<{stripejs}prestashop>settings_61c7e1201b6fd457bc9be7578b367d18'] = 'Vai su Impostazioni > Metodi di pagamento e fai clic sul pulsante Configura nella scheda Apple Pay.';
$_MODULE['<{stripejs}prestashop>settings_90fd33601dfdb49a836a4380b2bd3f18'] = 'Clicca sul pulsante \"Aggiungi nuovo dominio\" e segui la procedura indicata nell\'immagine sottostante.';
$_MODULE['<{stripejs}prestashop>settings_39ff7a78726d7b8277718caed64c6569'] = 'Il nome di dominio deve essere lo stesso. Controlla il WWW nel tuo dominio.';
$_MODULE['<{stripejs}prestashop>settings_3ca66554fb4bfc47bc0104f6d5670ab2'] = 'Perché sono necessari i webhook?';
$_MODULE['<{stripejs}prestashop>settings_b73549eb0b7653434cd547b2bade859a'] = 'Webhook è necessario per elaborare gli ordini per opzioni di pagamento basate su reindirizzamento come reindirizzamenti bancari locali, Stripe Checkout ecc.';
$_MODULE['<{stripejs}prestashop>settings_4b1adc85a56d3de832fe76acb5609f2f'] = 'Alcuni metodi di pagamento sono asincroni e i webhook sono l\'unico modo per mantenere aggiornati automaticamente i tuoi ordini.';
$_MODULE['<{stripejs}prestashop>settings_d3cf475b19ab31eb0ef8c954c3ee0166'] = 'Come posso aggiungere webhook Stripe?';
$_MODULE['<{stripejs}prestashop>settings_3438cbee21281ce6e3d6ab9df651a7c0'] = 'Dalla versione 4.7.1 o successiva, è necessario aggiungere manualmente un webhook utilizzando il collegamento fornito nella scheda \"Controlli tecnici\".';
$_MODULE['<{stripejs}prestashop>settings_19ba53247401754b494ccc514ee6b4a6'] = 'Dalle versioni 4.2.5 alla 4.6.9 di questo modulo, l\'endpoint Webhook verrà aggiunto automaticamente quando si salvano le chiavi API nella scheda \"Configurazione Stripe\".';
$_MODULE['<{stripejs}prestashop>settings_990982c946c47402dbdb2da37537b65a'] = 'Cruscotto Stripe';
